import{z as p,x as d,o as E,c as B,q as l,j as o,D as r,d as t,s as n,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"应用层背压","description":"","frontmatter":{"title":"应用层背压","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/app-backpressure.md","filePath":"cs/app-backpressure.md","lastUpdated":1791413859000}'),A={name:"cs/app-backpressure.md"};function C(c,a,P,m,h,u){const s=d("Mermaid");return E(),B("div",null,[a[2]||(a[2]=l('<h1 id="应用层背压" tabindex="-1">应用层背压 <a class="header-anchor" href="#应用层背压" aria-label="Permalink to &quot;应用层背压&quot;">​</a></h1><div class="epigraph"><p>慢消费者必须让生产者少发：窗口、阻塞写、队列上限或显式信号。否则内存当无限缓冲，延迟与 OOM 替代了丢包。</p><footer>—— 据 TCP 窗口对照；Reactive Streams 背压；RFC 9113 流控整理</footer></div><p><a href="/cs/tcp-window">TCP 窗口</a> 与 <a href="/cs/pause-pfc">PFC</a> 已给下层反压。<a href="/cs/c10k-concurrency">C10K</a> 的事件循环若盲目 <code>read</code> 会堆内存。<a href="/cs/retry-idempotency">上一课</a> 的重试会加重生产者。缺口是<strong>应用背压</strong>：把反压接到业务。本课结束计算机网络进阶；下一课进入数据库，先命名<a href="/cs/relational-model">关系模型</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>运输窗口满则 <code>write</code> 阻塞或 EAGAIN，这是 TCP 背压。应用若在用户态无限队列「先收着」，等于把膨胀搬进进程，心跳仍绿、业务已死。H2/QUIC 每流窗口是应用可见的运输背压。Reactive 流 <code>request(n)</code> 显式拉。令牌桶在入口限速是策略背压。SSE 若生产快于浏览器，要停生成器。</p><p>不要把杀进程当背压。</p><p><span class="marginnote">背压可以想象成水管下游堵了，水压顺着管子顶回上游，逼着水龙头关小。程序里同理：消费者处理不过来时，用某种信号让生产者少发或慢发。没有这根「回水管」，生产者只管发，多出来的数据就全靠内存替它兜着，兜到爆为止。</span></p><p><span class="marginnote">HTTP/2 流控。Reactive Streams 规范。本课钉原则。</span></p><h3 id="有界缓冲才是反压" tabindex="-1">有界缓冲才是反压 <a class="header-anchor" href="#有界缓冲才是反压" aria-label="Permalink to &quot;有界缓冲才是反压&quot;">​</a></h3><p>无限用户态队列取消 rwnd 的意义。可与 PFC、H2 窗口叠三层。重试在满载时要停。「先打进队列」只是改名膨胀。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：无限队列 / 有界队列阻塞 / 窗口 / 丢弃策略。画：快生产 → 信号 → 减速。与 DCTCP 浅队列同构，一层应用。</p>',12)),(E(),o(i,null,{default:r(()=>[n(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROD%5B%22%E7%94%9F%E4%BA%A7%E8%80%85%22%5D%20--%3E%20Q%5B%22%E6%9C%89%E7%95%8C%E9%98%9F%E5%88%97%22%5D%0A%20%20Q%20--%3E%20CONS%5B%22%E6%B6%88%E8%B4%B9%E8%80%85%22%5D%0A%20%20FULL%5B%22%E6%BB%A1%22%5D%20--%3E%20BP%5B%22%E9%98%BB%E5%A1%9E%E6%88%96%E7%AA%97%E5%8F%A3%E5%87%8F%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"rwnd（接收窗口）是接收方每次告诉发送方「我还能再收多少字节」的额度：额度大发得快，缩到 0 就必须停。它就是 TCP 自带的背压信号——本课做的事情，本质上是把这个「按接收方消化能力发货」的思想搬进应用代码。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"gRPC 流控、TCP rwnd、PFC 可叠三层；只开一层会在其它层爆。重试在背压时要停。负载均衡把溢出转到它机是横向背压。测量：队列深度与 p99，不是只看 iperf。",-1)),(E(),o(i,null,{default:r(()=>[n(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20CONS%5B%22%E6%85%A2%E6%B6%88%E8%B4%B9%E8%80%85%EF%BC%9A%E5%A4%84%E7%90%86%E8%B7%9F%E4%B8%8D%E4%B8%8A%22%5D%20--%3E%7C%22%E9%98%9F%E5%88%97%E6%BB%A1%EF%BC%8C%E6%9A%82%E5%81%9C%E6%8B%89%E5%8F%96%22%7C%20APP%5B%22%E5%BA%94%E7%94%A8%E5%B1%82%EF%BC%9A%E6%9C%89%E7%95%8C%E9%98%9F%E5%88%97%20%2F%20request(n)%22%5D%0A%20%20APP%20--%3E%7C%22%E7%BC%93%E5%86%B2%E5%A0%86%E7%A7%AF%EF%BC%8C%E6%8E%A5%E6%94%B6%E7%AA%97%E5%8F%A3%E6%94%B6%E7%BC%A9%22%7C%20TCP%5B%22%E4%BC%A0%E8%BE%93%E5%B1%82%EF%BC%9ATCP%20rwnd%22%5D%0A%20%20TCP%20--%3E%7C%22%E7%BD%91%E5%8D%A1%E7%BC%93%E5%86%B2%E5%90%83%E7%B4%A7%EF%BC%8C%E5%8F%91%20PAUSE%22%7C%20L2%5B%22%E9%93%BE%E8%B7%AF%E5%B1%82%EF%BC%9APFC%22%5D%0A%20%20L2%20--%3E%20SLOW%5B%22%E4%B8%8A%E6%B8%B8%E6%BA%90%E5%A4%B4%E5%87%8F%E9%80%9F%EF%BC%8C%E5%86%85%E5%AD%98%E4%B8%8D%E5%86%8D%E8%86%A8%E8%83%80%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">初学者容易以为服务「没挂」就没问题：心跳和存活探针只看进程活着，不看队列堆积。无限队列把崩溃推迟成延迟爆炸——p99 从 10 毫秒涨到 10 秒，用户早已流失，监控面板却还是绿的。所以要盯队列深度和 p99，而不是只看存活探针。</span></p><p>与端到端：最终仍要消费者处理完，背压只是保护途中内存。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入某语言异步库的全部 API。数据库课从<a href="/cs/relational-model">关系模型</a>另起，聚合不在此插入。后课默认：应用必须有界缓冲并向下反压。</p><p>「先打进 Kafka 再算」只是把膨胀换了个名字，仍要有界。</p><p>分组聚合在后面的<a href="/cs/sql-aggregation">聚合与 GROUP BY</a>一课展开。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无限用户态队列取消了运输窗口的意义。</li><li>用窗口、有界阻塞或显式 request。</li><li>与 PFC/rwnd 分层叠，不要只信一层。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 9113 流控；TCP 窗口；Reactive Streams。</li></ul>',8))])}const T=p(A,[["render",C]]);export{F as __pageData,T as default};
